import React from 'react';
import { Link } from 'react-router-dom';

const Leagues = ({ userId }) => {
  // In a real app, this is where you'd fetch the user's leagues
  return (
    <div>
      <h2>My Leagues</h2>
      <p>This page will list all the leagues you are a member of.</p>
      <Link to="/create-league">
        <button>Create a League</button>
      </Link>
    </div>
  );
};

export default Leagues;
